INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49511, 'Psalms 46:7', 'Psalms', 46, 7, 'مطلق قادر څښتن دی مل راسره د یعقوب خدای دی پناه ځای زمونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_7.mp3', '', 1761754199, 1761754199),
(49512, 'Psalms 46:8', 'Psalms', 46, 8, 'راشئ کارونه د څښتن وګورئ وګورئ څنګه هیبتناک کارونه وکړل په دنیا کې هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_8.mp3', '', 1761754199, 1761754199),
(49513, 'Psalms 46:9', 'Psalms', 46, 9, 'ټوله دنیا کې بندوي جنګونه لیندې له منځه وړي او نېزې ماتوي سېځي سپرونه په سور اور باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_9.mp3', '', 1761754199, 1761754199),
(49514, 'Psalms 46:10', 'Psalms', 46, 10, 'څښتن وویل: «جنګ بس کړئ په دې پوه شئ چې زه خدای یم ټولو قومونو څخه لوړ یمه زه ټولې دنیا باندې زه لوړ یمه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_10.mp3', '', 1761754199, 1761754199),
(49515, 'Psalms 46:11', 'Psalms', 46, 11, 'مطلق قادر څښتن دی مل راسره د یعقوب خدای دی پناه ځای زمونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_11.mp3', '', 1761754199, 1761754199),
(49516, 'Joshua 12:1', 'Joshua', 12, 1, 'مخکې له دې چې موسی مړ شي هغه او د اسراییلو خلکو د اردن د سیند د ختیځې خوا دوو پاچاهانو ته ماتې ورکړه. دې دوو پاچاهانو په هغې سیمې باندې چې د ارنون له درې څخه د حرمون تر غره پورې رسېدله او په هغې کې د اردن د درې ختیځه خوا هم شامله وه، حکومت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_1.mp3', '', 1761754199, 1761754199),
(49517, 'Joshua 12:2', 'Joshua', 12, 2, 'سیحون د اموریانو پاچا ؤ چې په حشبون کې یې پاچاهي کوله. هغه د عروعیر څخه چې د ارنون د درې په څنګ کې ؤ او د درې له منځ څخه د یبوق تر سیند پورې چې د عمونیانو پوله وه پاچاهي کوله. په دې کې نیم جلعاد شامل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_2.mp3', '', 1761754199, 1761754199),
(49518, 'Joshua 12:3', 'Joshua', 12, 3, 'په هغې کې د اردن دره د جلیل د بحیرې څخه جنوب خواته د بیت یشیموت (د مړې بحیرې ختیځ ته) او پیسګاه د غره تر لمنې پورې شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_3.mp3', '', 1761754199, 1761754199),
(49519, 'Joshua 12:4', 'Joshua', 12, 4, 'همدارنګه موسی او اسراییلیانو د باشان پاچا عوج ته چې د پاتې شویو رفاییانو څخه ؤ هم ماتې ورکړه. هغه په عشتاروت او ادرعي کې پاچاهي کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_4.mp3', '', 1761754199, 1761754199),
(49520, 'Joshua 12:5', 'Joshua', 12, 5, 'د هغه په پاچاهۍ کې د حرمون غر، سلخه او ټول باشان د جشور او معکې تر پولې او همدارنګه نیم جلعاد د حشبون د پاچا سیحون تر سیمې پورې شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_5.mp3', '', 1761754199, 1761754199),
(49521, 'Joshua 12:6', 'Joshua', 12, 6, 'موسی او د اسراییلو قوم دغو دوو پاچاهانو ته ماتې ورکړه. د څښتن خدمتګار موسی د هغوی خاوره د روبین او جاد قبیلو ته او د منسي نیمې قبیلې ته د هغوی د ملکیت په توګه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_6.mp3', '', 1761754199, 1761754199),
(49522, 'Joshua 12:7', 'Joshua', 12, 7, 'یوشع او د اسراییلو قوم هغو پاچاهانو ته چې د اردن د سیند په لوېدیځه خوا کې وو ماتې ورکړه، یعنې د بعل جاد څخه چې د لبنان په دره کې پروت ؤ د حالق تر غره پورې چې په جنوب کې ادوم ته نژدې ؤ. یوشع هغه ځمکه د اسراییلو د قبیلو ترمنځ ووېشله او د ملکیت په توګه یې هغوی ته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_7.mp3', '', 1761754199, 1761754199),
(49523, 'Joshua 12:8', 'Joshua', 12, 8, 'کومه ځمکه چې یوشع د هغوی په منځ کې ووېشله په هغې کې دا ځایونه شامل وو: غرنۍ سیمه، د غرونو لوېدیځې لمنې، د اردن دره، د غرونو ختیځ اړخونه او د کنعان جنوبي دښته. دا ځمکه د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو وطن ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_8.mp3', '', 1761754199, 1761754199),
(49524, 'Joshua 12:9', 'Joshua', 12, 9, 'د اسراییلو قوم د لاندېنیو ښارونو پاچاهانو ته ماتې ورکړه: اریحا، عای (بیت ییل ته نژدې)،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_9.mp3', '', 1761754199, 1761754199),
(49525, 'Joshua 12:10', 'Joshua', 12, 10, 'اورشلیم، حبرون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_10.mp3', '', 1761754199, 1761754199),
(49526, 'Joshua 12:11', 'Joshua', 12, 11, 'یرموت، لاخیش،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_11.mp3', '', 1761754199, 1761754199),
(49527, 'Joshua 12:12', 'Joshua', 12, 12, 'عجلون، جازر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_12.mp3', '', 1761754199, 1761754199),
(49528, 'Joshua 12:13', 'Joshua', 12, 13, 'دبیر، جدر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_13.mp3', '', 1761754199, 1761754199),
(49529, 'Joshua 12:14', 'Joshua', 12, 14, 'حرما، عراد،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_14.mp3', '', 1761754199, 1761754199),
(49530, 'Joshua 12:15', 'Joshua', 12, 15, 'لبنه، عدولام،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_15.mp3', '', 1761754199, 1761754199),
(49531, 'Joshua 12:16', 'Joshua', 12, 16, 'مقیده، بیت ییل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_16.mp3', '', 1761754199, 1761754199),
(49532, 'Joshua 12:17', 'Joshua', 12, 17, 'تفوح، حافر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_17.mp3', '', 1761754199, 1761754199),
(49533, 'Joshua 12:18', 'Joshua', 12, 18, 'عفیق، لشارون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_18.mp3', '', 1761754199, 1761754199),
(49534, 'Joshua 12:19', 'Joshua', 12, 19, 'مادون، حاصور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_19.mp3', '', 1761754199, 1761754199),
(49535, 'Joshua 12:20', 'Joshua', 12, 20, 'شمرون مرون، اخشاف،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_20.mp3', '', 1761754199, 1761754199),
(49536, 'Joshua 12:21', 'Joshua', 12, 21, 'تعنک، مجدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_21.mp3', '', 1761754199, 1761754199),
(49537, 'Joshua 12:22', 'Joshua', 12, 22, 'قادش، یقنعام (په کرمل کې)،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_22.mp3', '', 1761754199, 1761754199),
(49538, 'Joshua 12:23', 'Joshua', 12, 23, 'دور (د دور په لوړو سیمو)، قوییم (په جلیل کې)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_23.mp3', '', 1761754199, 1761754199),
(49539, 'Joshua 12:24', 'Joshua', 12, 24, 'او ترزه. د ټولو پاچاهانو شمېر یو دېرشو ته رسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua12_verse_24.mp3', '', 1761754199, 1761754199),
(49540, 'Psalms 71:1', 'Psalms', 71, 1, 'ما پناه راوړې تاته ای څښتنه! مه پرېږده مې ته هېڅکله خجالت ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_1.mp3', '', 1761754199, 1761754199),
(49541, 'Psalms 71:2', 'Psalms', 71, 2, 'ته عادل یې، کومک وکړه نجات راکړه دعا مې واوره او ما وژغوره ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_2.mp3', '', 1761754199, 1761754199),
(49542, 'Psalms 71:3', 'Psalms', 71, 3, 'اوسه زما ته پناه ځای خوندي چېرته چې تل زه راځم تا زما نجات دپاره امر کړی ځکه کلا او پناه ځای یې زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_3.mp3', '', 1761754199, 1761754199),
(49543, 'Psalms 71:4', 'Psalms', 71, 4, 'ای زما خدایه، ما کړه خلاص د بدعملو د لاسونو ځینې کړه ما راخلاص د بدکارانو ظالمانو د ولکې ځینې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_4.mp3', '', 1761754199, 1761754199),
(49544, 'Psalms 71:5', 'Psalms', 71, 5, 'څښتن تعالی، زما امید دی تاته لرم په تا باندې توکل زه د ځوانۍ له وخته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_5.mp3', '', 1761754199, 1761754199),
(49545, 'Psalms 71:6', 'Psalms', 71, 6, 'د زېږېدو نه مې مخکې ما په تا باندې تکیه کړې ده له هغه وخته دې ساتلی یم چې وم د مور په ګېډه کې زه زه ستا صفت به دوامداره کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_6.mp3', '', 1761754199, 1761754199),
(49546, 'Psalms 71:7', 'Psalms', 71, 7, 'ډېرو خلکو ته عبرت شو زما ژوند خو ته یې زما قوي پناه ځای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_7.mp3', '', 1761754199, 1761754199),
(49547, 'Psalms 71:8', 'Psalms', 71, 8, 'زه ټوله ورځ د ستا ثنا وایمه اعلانوم ستا جلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_8.mp3', '', 1761754199, 1761754199),
(49548, 'Psalms 71:9', 'Psalms', 71, 9, 'اوس چې زوړ شوی یمه له خپله ځانه مې ته لېرې نه کړې خوشې مې نه کړې چې کمزوری یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_9.mp3', '', 1761754199, 1761754199),
(49549, 'Psalms 71:10', 'Psalms', 71, 10, 'ځکه چې زما دښمنان زما په ضد خبرې کوي چې راپسې دي جوړوي زما د مرګ دسیسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_10.mp3', '', 1761754199, 1761754199),
(49550, 'Psalms 71:11', 'Psalms', 71, 11, 'هغوی وایي چې خدای پریښی هغه نو راځئ ورشو ورپسې راویې نیسو هېڅوک هم نشته چې کړي خلاص یې مونږ نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_11.mp3', '', 1761754199, 1761754199),
(49551, 'Psalms 71:12', 'Psalms', 71, 12, 'مه لېرې کېږه ما نه خدایه زما کومک ته زر راشه ای زما خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_12.mp3', '', 1761754199, 1761754199),
(49552, 'Psalms 71:13', 'Psalms', 71, 13, 'ودې شرمیږي او نابود دې شي څوک چې په ما پورې کوي تورونه څوک چې غواړي چې ضرر راته راورسوي شي شرمنده دې او رسوا دې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_13.mp3', '', 1761754199, 1761754199),
(49553, 'Psalms 71:14', 'Psalms', 71, 14, 'د امید سترګې مې تل ستا په لور دي ثنا او صفت به ستا لا زیات کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_14.mp3', '', 1761754199, 1761754199),
(49554, 'Psalms 71:15', 'Psalms', 71, 15, 'بیانوي به زما ژبه د ستا نېک کارونه ستا د نجات باره کې ټوله ورځ به کړي خبرې که څه هم دی زما د پوهې څخه لوړ دغه کار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_15.mp3', '', 1761754199, 1761754199),
(49555, 'Psalms 71:16', 'Psalms', 71, 16, 'زه به ځمه په قدرت د څښتن تعالی زه به اعلان ستا د عدالت کوم، یوازې ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_16.mp3', '', 1761754199, 1761754199),
(49556, 'Psalms 71:17', 'Psalms', 71, 17, 'د ماشومتوب نه دې تعلیم راکړی زه لا تر‌اوسه بیانوم ستا عجیبه کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_17.mp3', '', 1761754199, 1761754199),
(49557, 'Psalms 71:18', 'Psalms', 71, 18, 'اوس چې زه زوړ شوم او ویښتان مې سپین شول لاس رانه وانخلې ای خدایه ترڅو خبر کړمه دا نسل او نور ټول نسلونه ستا د قوت او ستا د زوره څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_18.mp3', '', 1761754199, 1761754199),
(49558, 'Psalms 71:19', 'Psalms', 71, 19, 'ای خدایه، ستا عدالت رسي تر اسمانه پورې تا کړي لوی کارونه نشته څوک ستا په مثل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_19.mp3', '', 1761754199, 1761754199),
(49559, 'Psalms 71:20', 'Psalms', 71, 20, 'تا تکلیفونه کړاوونه په ما راوستل خو ته به بېرته راته راکړې قوت ما به راوباسې د ځمکې د تل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_20.mp3', '', 1761754199, 1761754199),
(49560, 'Psalms 71:21', 'Psalms', 71, 21, 'ما به سرلوړی کړې له مخکې نه هم ماته به بېرته تسلي راکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_21.mp3', '', 1761754199, 1761754199),
(49561, 'Psalms 71:22', 'Psalms', 71, 22, 'زه به د چنګ په وهلو ستا صفت کړمه ځکه چې ته یې وفادار زما خدایه ای د اسراییلو سپېڅلی خدایه زه به په رباب به تاته وایمه سندره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_22.mp3', '', 1761754199, 1761754199),
(49562, 'Psalms 71:23', 'Psalms', 71, 23, 'زه درته وبه وهم د خوشحالۍ چیغې زه به سندرې درته وایمه د زړه له کومي ځکه چې تا راته نجات راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_23.mp3', '', 1761754199, 1761754199),
(49563, 'Psalms 71:24', 'Psalms', 71, 24, 'ستا د عدالت په هکله ټوله ورځ به زما ژبه کړي خبرې ځکه هغو چې کړ کوښښ چې ماته راکړي ضرر شول شرمنده او رسوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms71_verse_24.mp3', '', 1761754199, 1761754199),
(49564, 'Proverbs 27:1', 'Proverbs', 27, 1, 'د سبا ورځې د بریالیتوب په هکله لافې مه وهه ځکه ته نه پوهېږې چې سبا به څه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_1.mp3', '', 1761754199, 1761754199),
(49565, 'Proverbs 27:2', 'Proverbs', 27, 2, 'دا به ښه وي چې نور خلک ستا ستاینه وکړي هسې نه چې ته په خپله د ځان ستاینه وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_2.mp3', '', 1761754199, 1761754199),
(49566, 'Proverbs 27:3', 'Proverbs', 27, 3, 'کاڼي درانه او شګې درنې دي خو جاهل چې کومه غوسه راپاروي د دې نه هم درنه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_3.mp3', '', 1761754199, 1761754199),
(49567, 'Proverbs 27:4', 'Proverbs', 27, 4, 'غوسه ظالمه او غضب د سېلاب په څېر دی خو د کینې او غیرت په مخکې هېڅوک نه شي ټینګېدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_4.mp3', '', 1761754199, 1761754199),
(49568, 'Proverbs 27:5', 'Proverbs', 27, 5, 'له پټې مینې نه ښکاره رټنه ښه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_5.mp3', '', 1761754199, 1761754199),
(49569, 'Proverbs 27:6', 'Proverbs', 27, 6, 'د دوست له لاسه زخمونه د وفادارۍ نښه ده خو د دښمن په ډېرو ښکلولو باور نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_6.mp3', '', 1761754199, 1761754199),
(49570, 'Proverbs 27:7', 'Proverbs', 27, 7, 'موړ انسان د شاتو نه هم کرکه کوي خو د وږي دپاره ترخه خواړه هم خواږه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_7.mp3', '', 1761754199, 1761754199),
(49571, 'Proverbs 27:8', 'Proverbs', 27, 8, 'څوک چې له خپل کور نه بل ځای ته مسافر شي د هغې مرغۍ په شان ده چې له خپلې ځالې نه ورکه شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_8.mp3', '', 1761754199, 1761754199),
(49572, 'Proverbs 27:9', 'Proverbs', 27, 9, 'لکه څنګه چې عطر او خوشبویي د انسان زړه خوشحالوي نو همداسې ښې مشورې دوستان خوشحالوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_9.mp3', '', 1761754199, 1761754199),
(49573, 'Proverbs 27:10', 'Proverbs', 27, 10, 'د خپل ځان او خپل پلار دوستان مه پرېږده او د مصیبت په وخت کې د خپل ورور کور ته هم مه ځه ځکه ستا نژدې ګاونډی د لېرې ورور نه ښه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_10.mp3', '', 1761754199, 1761754199),
(49574, 'Proverbs 27:11', 'Proverbs', 27, 11, 'نو ای زما زویه! حکمت پیدا کړه او زما زړه خوشحاله کړه نو بیا زه هغه چاته ځواب ورکولای شم چې زما سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_11.mp3', '', 1761754199, 1761754199),
(49575, 'Proverbs 27:12', 'Proverbs', 27, 12, 'ځیرک انسان چې بدي او بلا ویني نو خپل ځان ترې ساتي خو ساده سړی چې د هغې په لور روان وي نو سزا به یې ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_12.mp3', '', 1761754199, 1761754199),
(49576, 'Proverbs 27:13', 'Proverbs', 27, 13, 'که څوک د یو پردي سړي ضمانت کوي نو کالي دې ترې ګرو واخلي او بیا دې د بل چا د ښځې په ضمانت کې د ځان سره امانت وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_13.mp3', '', 1761754199, 1761754199),
(49577, 'Proverbs 27:14', 'Proverbs', 27, 14, 'که څوک سهار وختي په لوړ اواز په خپل ګاونډي سلام اچوي نو دا به د ښکنځلو په څېر وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_14.mp3', '', 1761754199, 1761754199),
(49578, 'Proverbs 27:15', 'Proverbs', 27, 15, 'جګړه‌ماره ښځه د هغه بام سره برابره ده چې د باران په ورځ په پرله پسې توګه راڅاڅي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_15.mp3', '', 1761754199, 1761754199),
(49579, 'Proverbs 27:16', 'Proverbs', 27, 16, 'نو د هغې منع کول داسې دي لکه د باد بندول او یا تېل په موټي کې نیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_16.mp3', '', 1761754199, 1761754199),
(49580, 'Proverbs 27:17', 'Proverbs', 27, 17, 'لکه څنګه چې اوسپنه اوسپنه تېره کوي همداسې یو انسان بل انسان اصلاح کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_17.mp3', '', 1761754199, 1761754199),
(49581, 'Proverbs 27:18', 'Proverbs', 27, 18, 'لکه څنګه چې څوک د انځر د ونې پالنه کوي نو د هغې مېوه هم خوري همداسې که څوک د خپل بادار خیال ساتي نو عزت حاصلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_18.mp3', '', 1761754199, 1761754199),
(49582, 'Proverbs 27:19', 'Proverbs', 27, 19, 'لکه څنګه چې انسان خپل مخ په اوبو کې ویني همداسې د زړه سترګې د انسان شخصیت هم ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_19.mp3', '', 1761754199, 1761754199),
(49583, 'Proverbs 27:20', 'Proverbs', 27, 20, 'لکه څنګه چې قبر او د تباهۍ کنده په مرګ نه مړیږي همداسې د انسان سترګې هېڅکله هم نه مړیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_20.mp3', '', 1761754199, 1761754199),
(49584, 'Proverbs 27:21', 'Proverbs', 27, 21, 'لکه څنګه چې سره زر او سپین زر په اور ازمایل کیږي همداسې د انسان شخصیت د هغه صفت کولو څخه معلومیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_21.mp3', '', 1761754199, 1761754199),
(49585, 'Proverbs 27:22', 'Proverbs', 27, 22, 'که جاهل انسان په اونګ کې د تخم په شان وټکوې او د ډانګ په وسیله یې د غلو دانو په څېر میده میده کړې خو جهالت به ترې بیاهم لېرې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_22.mp3', '', 1761754199, 1761754199),
(49586, 'Proverbs 27:23', 'Proverbs', 27, 23, 'د خپلو رمو له حال نه ځان پوره خبروه او په ښه توګه د خپلو پادو باندې پام کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_23.mp3', '', 1761754199, 1761754199),
(49587, 'Proverbs 27:24', 'Proverbs', 27, 24, 'ځکه مال او دولت د تل دپاره نه وي او تاج او تخت نورو نسلونو ته نه پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_24.mp3', '', 1761754199, 1761754199),
(49588, 'Proverbs 27:25', 'Proverbs', 27, 25, 'کله چې واښه ورېبل شي او نوي تنکي واښه راشنه شي او د غرونو شنه بوټي راټول او ذخیره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_25.mp3', '', 1761754199, 1761754199),
(49589, 'Proverbs 27:26', 'Proverbs', 27, 26, 'نو بیا به ستا پسونه د کالیو دپاره وړۍ درکړي او د وزو په خرڅولو سره به ځمکه واخلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_26.mp3', '', 1761754199, 1761754199),
(49590, 'Proverbs 27:27', 'Proverbs', 27, 27, 'او بیا به ستا سره د وزو دومره ډېرې شیدې وي چې د کورنۍ ټول غړي به دې په ګېډه ماړه شي او د وینځو د ژوند دپاره به دې کافي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs27_verse_27.mp3', '', 1761754199, 1761754199),
(49591, 'Jeremiah 46:1', 'Jeremiah', 46, 1, 'مالِک خُدائ د غېر‌يهوديانو په حقله يرمياه نبى ته پېغام ورولېږلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_1.mp3', '', 1761754199, 1761754199),
(49592, 'Jeremiah 46:2', 'Jeremiah', 46, 2, 'کوم پېغام چې د مِصر په حقله وو هغه دا وو چې، د يهوداه بادشاه يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال، د کرکميس د جنګ په موقع کله چې فِرعون نِکوه د مِصر بادشاه او د هغۀ فوجيانو د فرات د سيند سره نزدې د بابل بادشاه نبوکدنضر نه شکست وخوړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_2.mp3', '', 1761754199, 1761754199),
(49593, 'Jeremiah 46:3', 'Jeremiah', 46, 3, '”خپل غټ او واړۀ ډالونه تيار کړئ او د جنګ دپاره راوځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_3.mp3', '', 1761754199, 1761754199),
(49594, 'Jeremiah 46:4', 'Jeremiah', 46, 4, 'خپل آسونه زين کړئ او ورباندې سوارۀ شئ. صفونه جوړ کړئ او د جنګ ټوپۍ په سر کړئ. خپلې نېزې تېرې کړئ، او زغره واچوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_4.mp3', '', 1761754199, 1761754199),
(49595, 'Jeremiah 46:5', 'Jeremiah', 46, 5, 'خو زۀ څۀ ګورم؟ چې په مِصرى فوجيانو باندې د يرې نه دهشت راغلے دے او هغوئ د يرې نه لګيا دى په شا کيږى، د هغوئ فوجيانو شکست وخوړلو. او په وارخطايۍ سره په مخه تښتى او هغوئ وروستو نۀ ګورى، او د هرې خوا نه په هغوئ باندې يره خوره شوې ده، مالِک خُدائ داسې فرمائيلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_5.mp3', '', 1761754199, 1761754199),
(49596, 'Jeremiah 46:6', 'Jeremiah', 46, 6, 'تېزه منډه وهونکے هم نۀ شى تښتېدلے، او نه تکړه فوجى تښتېدلے شى. او هغوئ په شمال کښې د فرات د سيند سره، تيندک خورى او راغورزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_6.mp3', '', 1761754199, 1761754199),
(49597, 'Jeremiah 46:7', 'Jeremiah', 46, 7, 'څوک دے دا چې لکه د نيل درياب په شان موجونه وهى، لکه د هغه سيند په شان چې اوبۀ يې په بره موجونه وهى او ټوله زمکه لاندې کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_7.mp3', '', 1761754199, 1761754199),
(49598, 'Jeremiah 46:8', 'Jeremiah', 46, 8, 'دا د مِصر فوج دے چې د نيل درياب په شان راوچت شوے دے او لافې وهى چې زۀ به راوچت شم او د سېلاب په شان به ټوله زمکه پټه کړم، زۀ به ټول ښارونه تباه کړم او په هغې کښې ټول خلق به هلاک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_8.mp3', '', 1761754199, 1761754199),
(49599, 'Jeremiah 46:9', 'Jeremiah', 46, 9, 'اے آسونو او جنګى ګاډو روان شئ، اے د مِصر تکړه سپاهيانو په دشمن حمله وکړئ، اے د ايتهوپيا، ليبيا، خلقو ډال راواخلئ او د لِديه خلقو څوک چې په غشو ليندو کښې تکړه يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_9.mp3', '', 1761754199, 1761754199),
(49600, 'Jeremiah 46:10', 'Jeremiah', 46, 10, 'ځکه چې دا د مالِک خُدائ ربُ الافواج ورځ ده، د انتقام ورځ، ځکه چې هغه به د خپلو دشمنانو نه انتقام واخلى. د هغۀ تُوره به تر هغې خوړل کوى ترڅو پورې چې مړه شوى نۀ وى، او ترڅو چې د هغوئ په وينو تنده ماته نۀ کړى. په نن ورځ به هغوئ مالِک خُدائ ربُ الافواج خُدائ پاک ته په شمال کښې د فرات د سيند سره د قربانۍ په شان پېش کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_10.mp3', '', 1761754199, 1761754199),
(49601, 'Jeremiah 46:11', 'Jeremiah', 46, 11, 'اے د مِصر پېغلې لورې، جِلعاد ته لاړه شه او هلته دارو ولټوه. خو ستاسو رنګارنګ دوائى به تاسو ته شفا درنۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_11.mp3', '', 1761754199, 1761754199),
(49602, 'Jeremiah 46:12', 'Jeremiah', 46, 12, 'قومونه به ستاسو د شرم په حقله خبر شى. زمکه به ستاسو دردناکه ژړا ډکه کړى. ستا تکړه فوجيان به په يو بل تيندک وخورى، او په يو ځائ به راپرېوځى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_12.mp3', '', 1761754199, 1761754199),
(49603, 'Jeremiah 46:13', 'Jeremiah', 46, 13, 'دا هغه خبر دے چې مالِک خُدائ د يرمياه نبى په وسيله د نبوکدنضر يعنې د بابل د بادشاه د راتلو او د هغۀ په مِصر باندې د حملې په حقله ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_13.mp3', '', 1761754199, 1761754199),
(49604, 'Jeremiah 46:14', 'Jeremiah', 46, 14, '”د مِصر په ښارونو په مجدال، ميمفِس او تحفنحيس کښې به دا اعلان وکړئ چې، د جنګ دپاره تيار شئ، ځکه چې تُوره به ستاسو خوا او شا کښې هر څۀ وخورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_14.mp3', '', 1761754199, 1761754199),
(49605, 'Jeremiah 46:15', 'Jeremiah', 46, 15, 'ستاسو جنګيالى ولې راغورزېدلى دى؟ هغوئ د مالِک خُدائ مخې ته نۀ شى ټينګېدلے ځکه چې هغه به هغوئ راوغورزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_15.mp3', '', 1761754199, 1761754199),
(49606, 'Jeremiah 46:16', 'Jeremiah', 46, 16, 'هغوئ به ټول تيندکونه خورى، او هغوئ به په يو بل راغورزيږى. هغوئ به يو بل ته وائى، پاڅه، راځئ چې خپلو خلقو او خپل مُلکونو ته واپس لاړ شُو، چرته به چې مونږ د ظالم د تُورې نه بچ شُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_16.mp3', '', 1761754199, 1761754199),
(49607, 'Jeremiah 46:17', 'Jeremiah', 46, 17, 'نو هغوئ به وائى چې د مِصر بادشاه فِرعون خو تش په خولۀ لوئيږى، هغۀ نه اوس خپله موقع خطا شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_17.mp3', '', 1761754199, 1761754199),
(49608, 'Jeremiah 46:18', 'Jeremiah', 46, 18, 'د دُنيا بادشاه د چا نوم چې مالِک خُدائ ربُ الافواج دے فرمائى چې، زما دې په خپل ذات قسم وى چې، يو کس څوک چې د مِصر خلاف راروان دے هغه لکه څنګه چې د تبور غر لوړ دے، او لکه څنګه چې د کرمل غر د سمندر په غاړه لوړ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_18.mp3', '', 1761754199, 1761754199),
(49609, 'Jeremiah 46:19', 'Jeremiah', 46, 19, 'اے د مِصر اوسېدونکو، خپل مال حال راواخلئ او د جلاوطنۍ دپاره تيار شئ، ځکه د ميمفِس ښار به تباه او کنډرې شى، او يو کس به هم په کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_19.mp3', '', 1761754199, 1761754199),
(49610, 'Jeremiah 46:20', 'Jeremiah', 46, 20, 'مِصر لکه د يوې ځوانې سخۍ په شان ښائسته دے، خو د شمال د خوا نه د هغۀ خلاف د غوباړى په شان مچ راروان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_20.mp3', '', 1761754199, 1761754199);